/* Definitions explain the terminology used by the teaching examples; lesson sources retain their own regulatory scope. */
window.MODULE_DEFINITIONS=[];
(() => {
 const add=(term,aliases,definition)=>MODULE_DEFINITIONS.push({term,aliases:aliases.split('|').filter(Boolean),definition});
 add('Asset','assets','An asset is a resource or contractual right with economic value. For a bank, examples include cash, securities and loans that customers are expected to repay.');
 add('Liability','liabilities','A liability is an obligation to transfer money or another resource. Customer deposits and a bank’s own borrowings are liabilities because the bank owes those amounts.');
 add('Equity','equities','Equity represents an ownership interest. On a bank balance sheet, equity is the residual interest in assets after liabilities; in a market-risk example, an equity position usually means shares in a company.');
 add('Principal','notional principal','Principal is the amount borrowed or invested before interest. A derivative’s notional principal is a reference amount used to calculate payments and may never be exchanged.');
 add('Notional','notionals','Notional is the reference amount used to scale a financial contract’s payments or exposure measures. It is not generally the contract’s market value or the amount that would be lost on default.');
 add('Cash flow','cash flows|cash-flow|cashflows','A cash flow is a payment or receipt at a specified time. Its amount, date, currency and legal owner affect both valuation and liquidity.');
 add('Present value','PV|present values','Present value is the value today of a future payment or stream of payments under the selected discounting assumptions. A payment received later is converted into today’s value using a discount factor.');
 add('Discount factor','discount factors','A discount factor is the multiplier that converts a future cash flow into present value. Its value depends on maturity and the discounting convention.');
 add('Discount rate','discounting|discount rates','A discount rate is a rate used to value future cash flows in present terms. The appropriate rate depends on the valuation framework and the characteristics of the cash flow.');
 add('Compounding','compounded|continuous compounding','Compounding describes how interest accumulates on principal and previously earned interest. Under continuous compounding, accumulation is represented by an exponential function rather than a sequence of periodic additions.');
 add('Maturity','maturities|remaining life','Maturity is the date or remaining period until a contract ends or principal becomes due. It can differ from an instrument’s next interest-rate reset or an option’s expiry.');
 add('Tenor','tenors|vertex|vertices','A tenor is a specified period, such as three months or five years. A curve vertex is a selected maturity point at which a rate or sensitivity is represented.');
 add('Basis point','bp|bps|basis points','One basis point is one hundredth of a percentage point. A rise from 4.00% to 4.01% is a one-basis-point increase.');
 add('Percentage point','percentage points|pp','A percentage point is the arithmetic difference between two percentages. An increase from 2% to 3% is one percentage point, but it is a 50% relative increase.');
 add('Currency codes','GBP|USD|EUR|JPY','GBP denotes pounds sterling, USD denotes US dollars, EUR denotes euros and JPY denotes Japanese yen. Currency labels matter because values and thresholds must be converted consistently before they are compared or combined.');
 add('Bond','bonds','A bond is a debt security under which an issuer promises specified payments to investors. Its value depends on the timing of those payments, discount rates and the risk of non-payment.');
 add('Coupon','coupons','A coupon is an interest payment on a bond or loan. The coupon rate determines the contractual payment; it is not necessarily the yield available to an investor at the current market price.');
 add('Yield','yields','Yield is a rate of return implied by a price and a specified set of cash flows under a stated convention. Different yield definitions and compounding conventions can produce different numerical rates.');
 add('Interest-rate swap','swap|swaps','An interest-rate swap exchanges interest payments calculated on a reference notional. A common swap exchanges fixed interest for floating interest, allowing the parties to change their exposure to future rates.');
 add('Receive-fixed and pay-fixed','receive-fixed|pay-fixed','A receive-fixed swap position receives fixed interest and pays floating interest; a pay-fixed position does the reverse. Their value sensitivities generally have opposite signs under the same contract and market assumptions.');
 add('Floating rate','floating|repricing','A floating rate resets according to a benchmark or contractual rule. Repricing occurs when the rate used to calculate a payment is updated, which need not coincide with repayment of principal.');
 add('Forward contract','forward|forwards','A forward contract fixes today the terms of a transaction to occur at a future date. The value of an existing forward changes as current market prices and financing conditions change.');
 add('Option','options|optionality','An option gives its holder a contractual choice, such as buying or selling an asset on specified terms. Optionality also occurs inside other products, for example when a borrower can repay early.');
 add('Call and put','call|put','A call gives the holder the right to buy the underlying on the contract’s terms. A put gives the right to sell it. The holder’s exercise choice makes the payoff asymmetric.');
 add('Strike','exercise price','The strike is the price specified in an option for buying or selling the underlying. Its position relative to the current underlying price helps determine the option’s value and sensitivities.');
 add('Expiry','expiration','Expiry is the time at which an option’s exercise right ends. A European option can be exercised only at expiry, while other exercise styles allow different choices.');
 add('Underlying','underlyings','The underlying is the asset, rate, index or other reference quantity on which a derivative’s payments depend. A derivative can depend on more than one underlying risk factor.');
 add('Spot price','spot','The spot price is the price or exchange rate for a transaction with the usual near-term settlement convention. It differs from a forward price agreed for a later transaction.');
 add('Payoff','payoffs','A payoff is the amount a contract produces in a specified outcome, usually at exercise or maturity. Its present value is not generally equal to the payoff because timing and uncertainty also matter.');
 add('At the money','ATM|moneyness','An option is at the money when its strike is close to the relevant underlying price or forward price under the stated convention. Moneyness describes that relationship more generally.');
 add('Long and short positions','long|short|shorted','A long position generally benefits from ownership or a rise in the relevant instrument’s value. A short position has the opposite exposure. For complex derivatives, the precise payment and sign convention should always be checked.');
 add('Volatility','vol|volatilities','Volatility measures the variability of a price, return or other risk factor over a stated period. It describes dispersion, not the direction in which the next move will occur.');
 add('Implied volatility','implied|volatility smile|smile','Implied volatility is the volatility parameter that makes a selected pricing model match an observed option price. A volatility smile or surface describes how implied volatility varies across strikes and expiries.');
 add('Normal and lognormal models','normal volatility|lognormal|log-normal','A normal model describes additive movements in a variable, while a lognormal model describes a positive variable whose logarithm is normally distributed. Their volatility inputs use different conventions and cannot be interchanged without conversion.');
 add('Risk factor','risk factors','A risk factor is a market or credit quantity whose movement affects a position’s value or loss. Examples include an interest rate, an exchange rate, a credit spread and an implied volatility.');
 add('Sensitivity','sensitivities|Greek|Greeks','A sensitivity measures how a value changes when a specified input changes, under a stated bump and unit convention. Greeks are familiar option sensitivities such as delta, gamma and vega.');
 add('DV01','PV01','DV01 measures the value effect associated with a one-basis-point interest-rate move. Some systems report a signed price change and others report a positive loss magnitude, so the lesson’s sign convention must be checked.');
 add('CS01','spread sensitivity','CS01 measures the value effect associated with a one-basis-point credit-spread move. A bond holder and a buyer of credit protection can have opposite signed CS01 values.');
 add('Delta','delta hedge','Delta is the first-order sensitivity of value to a specified underlying input. A delta hedge offsets that local exposure at the current point but may need adjustment when the market moves.');
 add('Gamma','convexity','Gamma measures how delta changes as the underlying changes. Convexity describes curvature more generally; bond convexity usually refers to the second-order relationship between price and yield.');
 add('Vega','vegas','Vega measures how value changes with the volatility input of a pricing model. A vega quoted per one volatility percentage point differs by a factor of 100 from a derivative taken with respect to volatility expressed as a decimal.');
 add('Curvature','CVR','Curvature describes the part of a value change that a first-order sensitivity does not capture. Its regulatory construction differs by framework: FRTB uses specified repricing shocks, whereas SIMM derives a curvature exposure from volatility-weighted vega and expiry scaling.');
 add('Finite difference','bump|bumped|finite-difference','A finite difference estimates a sensitivity by repricing after a small change in an input. The bump size, direction and units determine how the observed price change is converted into a sensitivity.');
 add('Hedge','hedges|hedging','A hedge is a position intended to offset part of another exposure. It can leave basis, timing, legal or non-linear risks and can introduce its own funding and counterparty demands.');
 add('Basis risk','basis','Basis risk arises when two related prices or rates do not move together as assumed. A hedge tied to one benchmark may therefore leave exposure to a different benchmark, location or contract specification.');
 add('Credit spread','spreads|spread','A credit spread is the additional yield or premium associated with credit exposure relative to a reference rate. It can reflect default risk, liquidity and other market effects, so it is not a direct default probability.');
 add('Credit default swap','CDS','A credit default swap exchanges a protection premium for a contractual payment if a specified credit event occurs. The protection buyer generally benefits when the reference credit deteriorates, subject to the contract’s terms.');
 add('Recovery and LGD','recovery|recoveries|loss given default|LGD','Recovery is the amount obtained after default, taking account of the relevant cash flows and costs. Loss given default, or LGD, is the fraction of exposure lost under the selected timing and discounting convention.');
 add('Hazard rate','hazard|intensity','A default hazard rate describes the instantaneous rate of default conditional on survival up to that time. A spread divided by LGD is a simplified hazard approximation, not a full credit-curve calibration.');
 add('Survival probability','survival','Survival probability is the probability that default has not occurred by a specified time. Its decline across an interval gives the probability of first default during that interval under the model.');
 add('Probability of default','PD|PDs','Probability of default is the probability that a borrower defaults over a defined horizon and under specified conditions. One-year, remaining-lifetime, market-implied and prudential PDs answer different questions.');
 add('Exposure at default','EAD','Exposure at default is the amount exposed when default occurs under the relevant model or regulatory definition. It can include future drawings or prescribed add-ons and need not equal today’s drawn balance.');
 add('Expected loss','EL','Expected loss is the probability-weighted average loss over a defined set of outcomes. In a simple single-period credit example it is PD multiplied by LGD and EAD, but richer models also account for timing and dependence.');
 add('Unexpected loss','loss dispersion','Unexpected loss describes uncertainty around the average loss rather than the average itself. Depending on the context, a model may summarise it using a standard deviation or a tail-loss measure.');
 add('Portfolio','portfolios','A portfolio is a collection of positions considered together. Its risk depends on their sizes, relationships and permitted offsets, not just the sum of their standalone risks.');
 add('Concentration','concentrated|HHI','Concentration means that a large share of exposure or funding depends on a small number of sources or common drivers. The Herfindahl–Hirschman Index, or HHI, sums squared shares to measure size concentration but does not by itself measure behavioural dependence.');
 add('Diversification','diversified','Diversification is the reduction in aggregate risk that can arise when positions do not experience adverse outcomes together. Its benefit depends on the chosen risk measure, dependence assumptions and any regulatory aggregation rules.');
 add('Correlation','correlated|correlations','Correlation summarises a specified relationship between two variables. A linear correlation does not fully describe joint tail behaviour, and a prescribed regulatory correlation is a model parameter rather than a measured relationship for every portfolio.');
 add('Covariance','covariance matrix','Covariance measures how two variables move together in their original units. A covariance matrix combines variances and pairwise covariances and is often used to aggregate sensitivities or model portfolio risk.');
 add('Standard deviation','SD|variance','Variance is the probability-weighted squared deviation from a mean. Standard deviation is its square root and is expressed in the original units of the variable.');
 add('Distribution','distributions','A probability distribution assigns probabilities to possible values or outcomes. It describes a range of possibilities rather than one realised observation.');
 add('Random variable','random variables','A random variable assigns a numerical value to each outcome in a probability model. Its expected value can be a weighted average that is not itself a possible individual outcome.');
 add('Expectation','expected value|conditional expectation','Expectation is an average weighted by the probabilities in a model. Conditional expectation updates that average using specified information and considers only the outcomes consistent with it.');
 add('Independence','independent','Variables are independent when learning the value of one does not change the probability distribution of the other. This is stronger than having zero linear correlation.');
 add('Binomial distribution','binomial|coin flips','A binomial distribution counts successes in a fixed number of independent trials with the same success probability. It is used here to make probabilities and replication in discrete outcomes easier to inspect.');
 add('Sigma-algebra and filtration','sigma-algebra|filtration','A sigma-algebra represents the events that can be distinguished with specified information. A filtration is a sequence of such information sets that grows through time.');
 add('Tower property','tower','The tower property says that averaging a conditional expectation over the conditioning information recovers the appropriate less-informed expectation. It ensures consistency between successive information updates.');
 add('Adapted and integrable','adapted|integrable','A process is adapted when its value at each time is determined by the information available then. Integrability is a mathematical condition ensuring that the relevant expected absolute value is finite.');
 add('Martingale','martingales','A martingale is an integrable, adapted process whose conditional expected future value equals its current value. Individual realised paths can still rise or fall substantially.');
 add('Random walk','scaled-walk|walk','A random walk is a process formed by adding successive random steps. Appropriate scaling of increasingly frequent independent steps can lead to a Brownian-motion limit.');
 add('Brownian motion','Brownian|Wiener','Brownian motion is a continuous stochastic process with independent, normally distributed increments whose variance equals the elapsed time. Its paths are continuous but are not differentiable in the ordinary calculus sense.');
 add('Drift and diffusion','drift|diffusion','Drift describes the predictable local direction of a stochastic process under a chosen probability measure. The diffusion term determines the magnitude of its continuous random fluctuations.');
 add('Random seed','seed|resample|simulation','A random seed fixes the sequence used by a pseudorandom simulation, making examples reproducible. Changing the seed generates a different sample without changing the model’s stated probability law.');
 add('Quadratic variation','quadratic-variation','Quadratic variation is the limit, when it exists, of sums of squared increments over increasingly fine partitions. Brownian motion has non-zero quadratic variation, which explains the extra term in Itô calculus.');
 add('Itô integral','ito-integral|Itô integration','An Itô integral accumulates a process against stochastic increments using information available before each increment. This non-anticipating construction differs from choosing an arbitrary ordinary-calculus integration rule.');
 add('Itô formula','ito-formula|Itô’s','Itô’s formula is the chain rule for suitable functions of stochastic processes. It includes an additional second-derivative term that accounts for the process’s quadratic variation.');
 add('Geometric Brownian motion','GBM|geometric-brownian','Geometric Brownian motion models proportional changes with constant drift and volatility parameters. It keeps prices positive but omits jumps and changing volatility in its basic form.');
 add('Risk-neutral measure','risk-neutral|measure','A risk-neutral measure is a pricing probability measure under which suitably discounted traded asset prices are martingales under the model’s conditions. Its probabilities are pricing weights and need not represent a real-world forecast.');
 add('Replication and no-arbitrage','replication|replicate|arbitrage|no-arbitrage','Replication constructs a portfolio with the same payoffs as a claim in the modelled states. No-arbitrage requires matching attainable payoffs to have consistent prices under the relevant financing and trading assumptions.');
 add('Girsanov’s theorem','girsanov|Radon–Nikodym|density process','Girsanov’s theorem describes how a suitable change of probability measure alters the drift of a stochastic process. The probability-density weighting must satisfy the theorem’s conditions; it is not an arbitrary reassignment of outcomes.');
 add('Black–Scholes','Black-Scholes','The Black–Scholes model values suitable European options under assumptions including continuous trading and constant model volatility. Its formula is useful for teaching how time, price and volatility affect option value, but its assumptions are restrictive.');
 add('Garman–Kohlhagen','Garman-Kohlhagen','The Garman–Kohlhagen model adapts the Black–Scholes framework to a currency option by including domestic and foreign interest rates. It retains similarly simplified volatility and market assumptions.');
 add('Feynman–Kac and PDE','Feynman|PDE|partial differential equation','The Feynman–Kac relationship connects certain conditional expectations of future payoffs with solutions of partial differential equations. In pricing, it links a probabilistic valuation to a differential-equation formulation under suitable conditions.');
 add('Monte Carlo estimation','Monte Carlo','Monte Carlo estimation approximates an expectation by averaging simulated outcomes. Sampling error decreases as more independent information is obtained, but additional simulations do not remove an incorrect model assumption.');
 add('Stopping time','stopping-times|optional stopping','A stopping time is a random time whose occurrence can be determined from information available up to that time. Optional-stopping results need additional conditions; stopping a strategy does not automatically create a profitable martingale strategy.');
 add('Barrier','barrier option','A barrier is a specified level whose crossing changes a contract’s payoff or ends a stopping-time experiment. Crossing risk depends on the path, not only the final value.');
 add('Mean reversion','mean-reverting|Vasicek|Ornstein','Mean reversion is the tendency of a modelled variable to move back towards a reference level. The Vasicek short-rate model uses a Gaussian mean-reverting process, which can produce negative rates.');
 add('Poisson process','Poisson|jumps|jump','A Poisson process counts randomly timed events with a specified intensity under its assumptions. Adding jumps allows a model to represent discontinuous changes that a purely continuous diffusion cannot generate.');
 add('Calibration','calibrated|recalibration','Calibration selects model parameters to match chosen data, market prices or target risk properties. A calibrated model can still be inappropriate if its structure or the selected evidence does not suit the task.');
 add('Yield curve','curves|term structure','A yield curve or term structure describes how rates or discount factors vary with maturity. Projection curves and discount curves can serve different purposes within one valuation.');
 add('Spot rate and zero rate','zero rate|spot rate','A zero or spot interest rate is the rate associated with discounting a single payment from a specified maturity to today under a stated compounding convention. It differs from a bond’s coupon rate.');
 add('Forward rate','forward rates','A forward rate is a rate implied for a future interval by the selected curve and its conventions. It is consistent with that curve’s pricing relationships but is not necessarily a forecast of the future realised rate.');
 add('Par rate','par quote|par-valued','A par rate is the coupon or fixed rate that makes an instrument’s value equal to its stated par value, or makes a swap have zero initial value, under the specified valuation conventions.');
 add('Bootstrapping','bootstrap|bootstrapped','Bootstrapping builds a curve sequentially by using market instruments to determine additional discount factors or rates once earlier points are known. The result depends on instrument selection and pricing conventions.');
 add('Interpolation','interpolate|log-linear','Interpolation supplies values between known curve points. Linear interpolation in rates and linear interpolation in logarithms of discount factors need not produce the same intermediate prices or sensitivities.');
 add('Day-count convention','ACT|day count|day-count','A day-count convention converts dates into year fractions for interest and valuation. For example, actual/365 uses the actual number of days divided by 365; other conventions produce different accrual fractions.');
 add('Accrual','accrued','Accrual allocates interest or other income and expense to the period in which it is earned or incurred. Accrued interest can make a settlement amount differ from a quoted clean bond price.');
 add('OIS','overnight-index|overnight index','An overnight indexed swap exchanges a fixed rate for a payment linked to compounded overnight rates. OIS curves are often relevant to collateralised discounting under the applicable currency and collateral conventions.');
 add('SONIA','Sterling Overnight Index Average','SONIA is the Sterling Overnight Index Average, a benchmark for overnight sterling borrowing transactions. Its publication and calculation conventions are maintained by the Bank of England.');
 add('Multiple curves','multi-curve|projection curve','A multiple-curve framework can use one curve to project a floating-rate cash flow and another to discount it. This allows different benchmark and collateral relationships to be represented consistently.');
 add('Trading book and banking book','trading-book|banking-book','The trading book and banking book are regulatory classifications with different risk treatments and boundary rules. They are not interchangeable labels that can be chosen solely to reduce a capital requirement.');
 add('FRTB','Fundamental Review','FRTB stands for the Fundamental Review of the Trading Book. It is the market-risk capital framework covered in the selected Basel and jurisdictional documents, including standardised and internal-models approaches.');
 add('PRA','Prudential Regulation Authority','The Prudential Regulation Authority is the UK prudential supervisor for the firms within its remit. PRA rules, supervisory statements and consultation proposals have different roles and legal status.');
 add('Basel, BCBS and IOSCO','Basel|BCBS|IOSCO','The Basel Committee on Banking Supervision develops international prudential standards for banks. IOSCO is the International Organization of Securities Commissions. International standards require the relevant jurisdictional implementation before they can be treated as local rules.');
 add('US NPR','NPR|notice of proposed rulemaking','A notice of proposed rulemaking presents proposed US regulatory text and an associated consultation. The proposal compared in this module is not treated as an implemented rule merely because it contains detailed calculations.');
 add('Regulatory capital and RWA','capital|RWA|risk-weighted assets','Regulatory capital is eligible loss-absorbing funding measured under the applicable rules. Risk-weighted assets express exposures or requirements on a risk-adjusted basis and are used with capital ratios; an exposure amount is not automatically a capital charge.');
 add('Standardised approach','SA|standardized','A standardised approach uses prescribed calculation structures and parameters, although some inputs still come from the bank’s portfolio and systems. The precise meaning depends on whether the framework concerns market risk, counterparty exposure or another risk.');
 add('Internal models approach','IMA','The internal models approach uses approved internal risk models within regulatory constraints. Model output alone does not establish eligibility; permission, data quality and ongoing tests also matter.');
 add('Sensitivities-based method','SBM','The sensitivities-based method is the FRTB standardised component for delta, vega and curvature risk. It weights and aggregates relevant sensitivities and repricing effects using the applicable bucket and correlation rules.');
 add('Risk class and bucket','bucket|buckets|risk class','A risk class groups related risk types, such as interest rates or equities. A bucket is a further prescribed grouping used in aggregation. The definitions differ across FRTB, SA-CVA and SIMM.');
 add('Risk weight and weighted sensitivity','RW|WS|weighted sensitivities','A risk weight scales a relevant exposure or sensitivity according to the framework. A weighted sensitivity retains the required sign and is then combined with other weighted sensitivities under the applicable aggregation rules.');
 add('General interest-rate risk','GIRR','GIRR is the FRTB risk class for general interest-rate factors, including the specified curve, inflation and cross-currency basis risks. It is distinct from credit-spread risk.');
 add('Credit-spread risk','CSR','Credit-spread risk is the risk of value changes caused by movements in credit spreads. FRTB distinguishes non-securitisation, securitisation outside the alternative correlation trading portfolio and alternative correlation trading portfolio treatments.');
 add('Securitisation and tranche','securitisation|securitization|tranche|tranches','A securitisation allocates cash flows and credit losses from a pool of exposures to securities or positions. A tranche has a specified priority and loss-absorption range, so its risk can differ substantially from the average risk of the pool.');
 add('ABS, RMBS and CDO','ABS|RMBS|CDO','Asset-backed securities are backed by a pool of assets. Residential mortgage-backed securities are backed by residential mortgages. A collateralised debt obligation divides exposure to a debt portfolio into tranches under its structure.');
 add('Alternative correlation trading portfolio','ACTP|non-ACTP','The alternative correlation trading portfolio is a defined FRTB category with specific eligibility and calculation rules. Securitisation positions outside that category receive a different treatment; a model user cannot assign membership solely to obtain a preferred charge.');
 add('Investment grade and high yield','IG|HY|BBB|AA|rating','Investment grade and high yield are credit-quality groupings based on the relevant rating or classification rules. Rating labels such as AA and BBB indicate categories, not guarantees of repayment.');
 add('Default risk charge','DRC','The default risk charge is the FRTB capital component addressing issuer default losses. Its calculation is distinct from ordinary price sensitivities and from counterparty exposure on a derivative.');
 add('Jump to default','JTD','Jump to default measures the relevant change in value or loss if the reference issuer defaults, under the framework’s conventions. Eligible netting, maturity scaling, seniority and caps can affect the amount used in capital.');
 add('Seniority','senior|subordinated','Seniority describes a claim’s priority relative to other claims on an issuer. It affects recovery and can determine whether positions are permitted to offset in a default-risk calculation.');
 add('Residual risk add-on','RRAO','The residual risk add-on is the FRTB standardised charge for specified risks that the other components do not adequately capture. Its prescribed gross-notional basis and exemptions differ from ordinary sensitivity netting.');
 add('Value at Risk','VaR|quantile','Value at Risk is a loss threshold at a chosen confidence level over a specified horizon. It does not describe how severe losses beyond that threshold may be. A quantile is the corresponding threshold in a probability distribution.');
 add('Expected shortfall','ES|tail loss','Expected shortfall averages losses in a specified worst part of the loss distribution. Its treatment of probability mass at the threshold matters for discrete scenario samples.');
 add('Liquidity horizon','LH|holding period','A liquidity horizon is the period used to represent how long risk may take to hedge or close under the applicable framework. FRTB liquidity-horizon adjustments are not interchangeable with an arbitrary scaling of a portfolio VaR.');
 add('Stress calibration','stressed|stress period','Stress calibration uses a defined adverse market period or scenario to set a model’s risk scale. The data window, factor set and aggregation method determine what the resulting stressed measure represents.');
 add('Full and reduced factor sets','FC|RC|PES','FRTB internal-models calculations distinguish a full risk-factor set from a reduced set used for stress calibration. Labels such as FC and RC in the applets refer to full-current and reduced-current measures; RC in SA-CCR instead means replacement cost. PES labels the supplied partial expected-shortfall inputs in the relevant FRTB lesson.');
 add('Constrained and unconstrained expected shortfall','UES|IMCC|constrained','Unconstrained expected shortfall reflects the permitted joint-portfolio calculation. The constrained component restricts diversification across broad risk classes. The FRTB models-based capital calculation combines the specified measures rather than allowing arbitrary diversification assumptions.');
 add('Risk factor eligibility test','RFET','The risk factor eligibility test assesses whether a risk factor has sufficient qualifying real-price observations to be treated as modellable under the relevant rules. Observation dates and mapping matter, not just the annual count.');
 add('Non-modellable risk factor','NMRF|NMRFs','A non-modellable risk factor does not meet the applicable modellability requirements for the ordinary internal-model calculation. Its risk is addressed through the specified stressed treatment rather than ignored.');
 add('Stressed NMRF charge','SSRM|SES|stress scenario risk measure','The stressed risk measure for non-modellable factors estimates their capital contribution under the applicable stress and aggregation rules. The selected documents use different labels, including SSRM and stressed expected shortfall, so the cited definition must be checked.');
 add('Profit-and-loss attribution','PLAT|PLA','Profit-and-loss attribution compares risk-theoretical P&L with hypothetical P&L to assess whether the model captures the desk’s relevant risk drivers. Its eligibility consequences and thresholds depend on the applicable rules.');
 add('Actual, hypothetical and risk-theoretical P&L','APL|HPL|RTPL|P&L','P&L means profit and loss. Actual P&L follows the applicable realised desk calculation; hypothetical P&L revalues a specified static portfolio; risk-theoretical P&L uses the risk factors represented by the model. Their definitions and exclusions must be matched before comparing them.');
 add('Spearman and KS statistics','Spearman|KS|Kolmogorov','Spearman correlation compares the rank ordering of observations. The Kolmogorov–Smirnov statistic compares empirical cumulative distributions. Neither statistic alone explains the economic source of a model discrepancy.');
 add('RMS error','RMS|root mean square','Root mean square error summarises the size of a set of differences by squaring them, averaging and taking a square root. It is non-negative and is expressed in the original measurement units.');
 add('Backtesting','backtest|breach|exceedance','Backtesting compares model outputs with subsequent or historical outcomes under a defined testing convention. A breach or exceedance occurs when the observed loss is beyond the relevant model threshold; count, size and data dependence all affect interpretation.');
 add('Standardised fallback and CU','fallback|CU','A standardised fallback applies the prescribed standardised treatment to positions or desks that are not eligible for the internal-model route. CU denotes the standardised charge for ineligible desks in the specific FRTB capital example, with its scope stated there.');
 add('Idiosyncratic and systematic risk','idiosyncratic|systematic','Idiosyncratic risk is specific to a name or position, while systematic risk is driven by factors shared across many positions. The distinction affects diversification assumptions and some regulatory aggregation treatments.');
 add('Index decomposition','index|indices|look-through','Index decomposition represents a position through exposures to its constituents when the relevant framework permits or requires it. Delta, vega and curvature can have different index treatments, so look-through should not be applied indiscriminately.');
 add('OTC and clearing','OTC|non-cleared|cleared','An over-the-counter derivative is negotiated outside a traditional exchange trading arrangement. Clearing through a central counterparty changes counterparty and collateral arrangements; an OTC trade may be centrally cleared or remain bilateral.');
 add('Counterparty credit risk','CCR|counterparty','Counterparty credit risk is the risk of loss when the other party to a financial contract fails to perform. For derivatives, exposure can change with market conditions and may be positive for either party at different times.');
 add('Netting set','netting|netted','A netting set contains transactions that can be combined under the relevant legally recognised agreement and calculation rules. Economic offsets across different legal sets do not automatically qualify as regulatory or collateral offsets.');
 add('Credit support annex','CSA|margin agreement','A credit support annex or comparable margin agreement sets out collateral obligations, eligible assets and transfer mechanics. Its terms affect exposure, funding and the timing of collateral payments.');
 add('Collateral','collateralised|collateralized','Collateral is cash or another eligible asset provided to secure an obligation. Its protection depends on value, legal enforceability, availability and the time required to realise it.');
 add('Haircut','haircuts','A haircut reduces the recognised value of collateral or an asset pool for a specified calculation. It accounts for the relevant risk or rule and is not necessarily the price discount obtained in an actual sale.');
 add('Threshold and MTA','TH|MTA|minimum transfer amount','A threshold defines an amount that may remain unsecured or uncollateralised under the applicable arrangement. A minimum transfer amount limits small collateral transfers. Their legal scope and treatment differ across regulatory and contractual contexts.');
 add('Variation margin','VM','Variation margin addresses changes in current exposure by transferring collateral according to the agreement. A received or posted amount is a cash or collateral flow, not an additional valuation profit by itself.');
 add('Initial margin','IM','Initial margin is a buffer for potential adverse value movements during the period needed to close or replace positions after default. It is separate from variation margin and can create a funding requirement for the posting party.');
 add('Margin period of risk','MPOR','The margin period of risk is the period over which exposure can change between the relevant collateral snapshot and effective close-out or replacement. Operational delays and contractual conditions can affect its required treatment.');
 add('CVA','credit valuation adjustment','Credit valuation adjustment reduces a default-free value to reflect expected loss from counterparty default under the selected valuation framework. The value of CVA and the capital held against changes in CVA are different measures.');
 add('SA-CVA and BA-CVA','SA-CVA|BA-CVA','SA-CVA is the standardised approach to CVA risk capital and uses the relevant sensitivities and eligible hedges. BA-CVA is the basic approach under its own rules. Permissions and portfolio scope determine which treatment applies.');
 add('Expected positive exposure','EPE|EE|positive exposure','Positive exposure is the amount at risk when the counterparty owes the bank money in a specified state. Expected exposure averages positive exposure across scenarios at a time; expected positive exposure is also used in regulatory contexts for a specified time average, so the exact definition must be checked.');
 add('Wrong-way risk','wrong-way|right-way','Wrong-way risk occurs when exposure increases in conditions associated with a greater likelihood or severity of counterparty loss. Right-way dependence moves in the opposite direction, but the model and evidence must establish the relationship.');
 add('SA-CCR','standardised approach for counterparty','SA-CCR is the standardised approach for counterparty credit risk. It combines replacement cost and potential future exposure, with the relevant alpha treatment, to produce a regulatory exposure-at-default amount.');
 add('Replacement cost','RC|CMV|current market value','Replacement cost is the current exposure component in SA-CCR under the applicable netting and collateral rules. Current market value, or CMV, is an input; replacement cost need not equal an unadjusted positive trade value.');
 add('Potential future exposure','PFE','Potential future exposure allows for an increase in exposure after the current snapshot. In SA-CCR it is calculated through a prescribed multiplier and aggregate add-on, which differs from a generic simulated exposure quantile.');
 add('Net independent collateral amount','NICA','NICA is the net independent collateral amount defined for the SA-CCR calculation. Its treatment depends on whether collateral is received or posted and on the applicable legal and segregation conditions.');
 add('Alpha','α','Alpha is the multiplier used in the relevant regulatory exposure formula. Its value and any conditional treatment must be taken from the applicable framework and jurisdiction, rather than assumed from a different version of the rules.');
 add('Supervisory delta','supervisory delta','Supervisory delta is a prescribed representation of trade direction and optionality used in SA-CCR. It is a regulatory calculation input and need not equal the market delta used to hedge the instrument.');
 add('Supervisory duration','adjusted notional|duration adjustment','Supervisory duration transforms the relevant interest-rate or credit trade notional using prescribed start and end dates. Adjusted notional is the resulting exposure scale, with different definitions for other asset classes.');
 add('Supervisory factor and maturity factor','SF|MF|maturity factor|supervisory factor','A supervisory factor scales the risk of the relevant SA-CCR exposure category. A maturity factor adjusts for the applicable maturity or margin-period convention. These are different inputs and should not be confused with market volatility estimates.');
 add('Hedging set','hedging sets','A hedging set is a defined grouping within the applicable counterparty-exposure calculation. The grouping determines which trade exposures can offset and which correlation or aggregation rules apply.');
 add('XVA','valuation adjustments|VA','XVA is a collective label for valuation adjustments addressing credit, funding, collateral, capital and related effects. The adjustments must be combined consistently within a valuation framework to avoid double counting.');
 add('DVA','debit valuation adjustment|own credit','Debit valuation adjustment reflects the effect of the bank’s own default risk on the value of its obligations under a bilateral valuation framework. It is not an amount of cash that can automatically be used to fund a position.');
 add('FVA, FCA and FBA','FVA|FCA|FBA','Funding valuation adjustment represents the relevant funding effects in a valuation framework. Funding cost adjustment and funding benefit adjustment distinguish cost and benefit components, subject to the model’s treatment of collateral and own credit.');
 add('Collateral and liquidity valuation adjustments','LVA|collateral valuation|liquidity valuation','Collateral and liquidity valuation adjustments represent the value effects of collateral remuneration or related liquidity and financing differences under a stated framework. Their labels and boundaries are not universal across institutions.');
 add('MVA','margin valuation adjustment','Margin valuation adjustment represents the value of funding initial margin over the relevant future life of a portfolio. It depends on projected margin and funding assumptions, not just the initial margin balance today.');
 add('KVA','capital valuation adjustment','Capital valuation adjustment represents the value of the cost of supporting a trade or portfolio with capital under a specified framework. It depends on future capital requirements, remuneration assumptions and valuation conventions.');
 add('TVA','tax valuation adjustment','Tax valuation adjustment represents tax-related effects included by a specified valuation framework. The relevant treatment depends on the jurisdiction, cash flows and assumptions rather than a universal add-on percentage.');
 add('AVA and prudent valuation','AVA|additional valuation adjustment|prudent valuation','An additional valuation adjustment recognises specified valuation uncertainty under a prudent-valuation framework. It is distinct from expected credit loss and from a trading desk’s chosen pricing adjustment.');
 add('CCP, default fund and CCVA','CCP|CCVA|DF|default fund','A central counterparty interposes itself between clearing participants. Its default fund supports the specified loss-allocation arrangements. CCVA denotes the clearing-related valuation adjustment in the relevant lesson, whose components are defined by the cited model.');
 add('IRRBB and CSRBB','IRRBB|CSRBB','IRRBB is interest-rate risk in the banking book and concerns earnings and economic-value effects. CSRBB is credit-spread risk in the banking book and addresses relevant spread movements that are distinct from general interest-rate changes.');
 add('Net interest income','NII|ΔNII','Net interest income is interest earned on assets minus interest paid on funding over a defined period. Delta NII is the change in that income under a specified scenario relative to a baseline.');
 add('Economic value of equity','EVE|ΔEVE','Economic value of equity compares the present value of the relevant asset and liability cash flows under the chosen measurement convention. Delta EVE is the scenario change in that value and is not the same as a short-term earnings change.');
 add('Modified duration','duration|DV01','Modified duration measures the approximate proportional price response to a small yield change under its convention. It is distinct from contractual maturity and from supervisory duration used in SA-CCR.');
 add('Non-maturity deposit','NMD|non-maturity','A non-maturity deposit has no fixed contractual final maturity of the usual term-deposit kind. Its behavioural repricing and withdrawal assumptions can differ substantially from its contractual availability to the customer.');
 add('Deposit beta and lag','beta|deposit beta|lag','Deposit beta measures the proportion of a market-rate change passed into the customer deposit rate. Lag measures the delay before that repricing occurs; neither is a deposit withdrawal rate.');
 add('Prepayment and CPR','prepayment|CPR','Prepayment occurs when principal is repaid earlier than the expected or contractual schedule. The conditional prepayment rate is an annualised measure applied to the surviving balance under the stated convention.');
 add('Reinvestment risk','reinvestment','Reinvestment risk is the risk that returned principal or income must be invested on less favourable terms. Early repayment can improve immediate liquidity while reducing future interest income.');
 add('Liquidity and solvency','liquidity|solvency|solvent','Liquidity concerns the ability to meet obligations when due. Solvency concerns the ability of assets and loss-absorbing resources to cover liabilities and losses; a solvent institution can still face a timed cash shortage.');
 add('Funding and rollover risk','funding|rollover|refinancing','Funding supports assets and payment obligations through deposits, borrowing and other sources. Rollover risk is the risk that maturing funding cannot be replaced at an acceptable cost or at all.');
 add('Wholesale and retail funding','wholesale|retail','Retail funding generally comes from individual customers or qualifying small businesses, while wholesale funding comes from financial markets and larger institutional sources. Regulatory classifications and stability assumptions require more detail than these broad labels.');
 add('Runoff','withdrawal|outflow','Runoff describes the amount or fraction of a funding balance assumed to leave over a specified period. A regulatory runoff rate and an internally chosen behavioural stress assumption are different inputs.');
 add('HQLA','high-quality liquid assets|Level 1|Level 2A|Level 2B','High-quality liquid assets are assets meeting the relevant liquidity-standard eligibility and operational criteria. Level 1, Level 2A and Level 2B classifications carry different prescribed haircuts and composition constraints.');
 add('LCR','liquidity coverage ratio','The liquidity coverage ratio compares adjusted HQLA with prescribed net cash outflows over a 30-day stress period. The general inflow cap limits how much expected inflow can reduce the denominator, subject to applicable exceptions.');
 add('NSFR, ASF and RSF','NSFR|ASF|RSF|net stable funding ratio','The net stable funding ratio compares available stable funding with required stable funding. ASF weights funding sources by the applicable stability treatment, while RSF weights assets and other requirements by their need for stable funding.');
 add('Encumbrance','encumbered|unencumbered','An encumbered asset is pledged or otherwise restricted in a way that limits its availability. An unencumbered asset is not automatically usable immediately; eligibility, location and operational readiness still matter.');
 add('Repo','repurchase agreement','A repurchase agreement raises cash against securities under an agreement to reverse the transaction. It creates a funding and repayment relationship and differs from an outright asset sale.');
 add('Intraday liquidity','intraday','Intraday liquidity is the ability to meet payment and settlement obligations during the day. A positive closing cash balance can hide an earlier shortage if outgoing payments precede incoming funds.');
 add('Counterbalancing capacity','monetisation|monetisable','Counterbalancing capacity is the liquidity that credible management actions can generate under the relevant scenario and constraints. Capacity should not be treated as settled cash before the action can actually be completed.');
 add('Funds transfer pricing','FTP','Funds transfer pricing allocates funding costs and benefits internally to the businesses that create them. It helps reflect tenor, currency, liquidity and optionality but does not create additional profit for the consolidated bank.');
 add('Carry and opportunity cost','carry|opportunity cost','Carry is the ongoing income or expense from holding and financing a position. Opportunity cost compares that choice with a specified alternative, whose credit, capital and liquidity risks may differ.');
 add('FX swap and forward points','FX swap|forward points|cross-currency','An FX swap exchanges currencies now and reverses the exchange at a later date. Forward points express the difference between forward and spot exchange rates; basis and market conventions affect the all-in funding interpretation.');
 add('Natural hedge','natural hedges','A natural hedge offsets exposure through underlying receipts and payments, such as cash flows in the same currency. Timing, amount and legal availability must align for the offset to be effective.');
 add('Payment versus payment','PvP|PVP|settlement risk','Payment versus payment makes settlement of one currency conditional on settlement of the other. It mitigates principal settlement risk but leaves liquidity, operational and replacement-cost risks to manage.');
 add('Trapped liquidity','trapped cash|transferability','Trapped liquidity is cash or funding capacity that cannot reach the entity or currency with an obligation when needed. Legal restrictions, regulation, operational limits and settlement cut-offs can all reduce transferability.');
 add('Risk appetite and limits','risk appetite|early warning|internal limit','Risk appetite describes the types and amounts of risk an organisation is willing to accept under its governance. Limits and early-warning indicators translate that position into monitored measures and escalation triggers.');
 add('Stress and reverse stress testing','stress testing|reverse stress','Stress testing examines the effect of specified adverse conditions. Reverse stress testing starts with an unacceptable outcome and asks what conditions could cause it, without automatically assigning those conditions a probability.');
 add('Contingency funding plan','contingency|recovery plan','A contingency funding plan identifies actions, owners and triggers for dealing with liquidity stress. A broader recovery plan addresses restoration of financial viability under the applicable framework; the two plans must be consistent but are not identical.');
 add('ALCO','Asset and Liability Committee','The Asset and Liability Committee considers balance-sheet risks and trade-offs such as funding, liquidity, earnings and economic value. Its precise authority and reporting responsibilities depend on the organisation’s governance.');
 add('ILAAP and ICAAP','ILAAP|ICAAP','The Internal Liquidity Adequacy Assessment Process evaluates liquidity and funding adequacy. The Internal Capital Adequacy Assessment Process evaluates capital adequacy. Both connect risk assessment, evidence and governance to management decisions.');
 add('IFRS 9','IFRS|International Financial Reporting Standard','IFRS 9 is the financial reporting standard covering relevant classification, measurement, impairment and hedge-accounting requirements for financial instruments. The credit module focuses on its expected-credit-loss concepts and distinguishes them from regulatory capital rules.');
 add('Expected credit loss','ECL|ECLs','Expected credit loss is a probability-weighted estimate of credit cash shortfalls measured under IFRS 9’s applicable requirements. Timing, discounting, reasonable and supportable information, and the relevant measurement horizon matter.');
 add('Twelve-month and lifetime ECL','12-month|12m|lifetime','Twelve-month ECL concerns lifetime cash shortfalls associated with defaults that are possible in the next twelve months. Lifetime ECL concerns defaults possible over the relevant expected life; twelve-month ECL is not simply the next year’s missed payments.');
 add('SICR and staging','SICR|Stage 1|Stage 2|Stage 3','A significant increase in credit risk can move a qualifying asset from Stage 1 to Stage 2 under IFRS 9’s general approach. Stage 3 concerns credit-impaired assets. Staging reflects the applicable assessment and is not determined by an arbitrary universal PD cutoff.');
 add('Days past due','DPD|past due','Days past due counts how long a contractual payment has remained unpaid. IFRS 9 uses rebuttable presumptions in specified circumstances, but a complete credit assessment also considers other relevant evidence.');
 add('Effective interest rate','EIR','The effective interest rate discounts the relevant estimated contractual cash flows to the carrying amount under the accounting requirements. Credit-adjusted EIR has a distinct role for purchased or originated credit-impaired assets.');
 add('POCI','purchased or originated credit-impaired','Purchased or originated credit-impaired assets are already credit-impaired at initial recognition. Their credit-adjusted effective-interest and impairment treatment differs from applying the ordinary Stage 1-to-Stage 3 sequence to a newly performing loan.');
 add('Amortised cost and carrying amount','amortised|amortized|carrying amount','Amortised cost is an accounting measurement that updates the recognised amount using the effective-interest method and relevant payments or adjustments. Gross and net carrying amounts differ where a loss allowance is recognised.');
 add('SPPI and business model','SPPI|business model','SPPI asks whether contractual cash flows are solely payments of principal and interest under IFRS 9’s conditions. Classification also depends on the relevant business-model assessment, rather than on SPPI alone.');
 add('FVOCI, FVTPL and OCI','FVOCI|FVTPL|OCI','FVOCI means fair value through other comprehensive income, while FVTPL means fair value through profit or loss. OCI is other comprehensive income, a presentation category whose treatment differs from ordinary period profit or loss.');
 add('Credit conversion factor','CCF','A credit conversion factor estimates or prescribes how much of an undrawn commitment contributes to exposure. Behavioural estimates and regulatory factors should not be substituted for one another without checking the purpose of the calculation.');
 add('Revolving facility','revolving|commitment','A revolving facility allows borrowing, repayment and further drawing within contractual terms. Its exposure and expected life can depend on customer behaviour and the lender’s ability to mitigate credit risk.');
 add('Conditional, marginal and cumulative PD','conditional PD|marginal PD|cumulative PD','Conditional PD applies to borrowers still surviving at the start of an interval. Marginal PD is the probability of first default during that interval from the original population, while cumulative PD is the probability of default by a specified date.');
 add('Point-in-time and through-the-cycle','PIT|TTC','A point-in-time estimate reflects current conditions more directly. A through-the-cycle estimate aims to represent risk across the cycle under its definition. Neither label alone specifies a complete calibration method or accounting suitability.');
 add('Rating migration','migration|transition matrix','Rating migration is movement between credit-quality states. A transition matrix records the probabilities of those movements over a stated period, often including an absorbing default state in simplified examples.');
 add('Loan-to-value ratio','LTV','The loan-to-value ratio compares a loan exposure with the value of its supporting collateral under a specified convention. Collateral value, enforcement cost and recovery timing still affect the eventual loss.');
 add('SME','small business','SME means small or medium-sized enterprise. Accounting, regulatory and modelling classifications can impose specific size or eligibility criteria beyond that general description.');
 add('Vintage and cohort','vintage|cohort','A cohort is a group observed from a common starting condition, such as an origination period. Vintage analysis follows such groups over time to distinguish seasoning and changing lending conditions from other effects.');
 add('Censoring','censored','Censoring occurs when a record’s full outcome is not observed within the available follow-up period. Treating all censored borrowers as permanent non-defaults can bias estimated default behaviour.');
 add('Variable selection','feature|predictor|variables','Variable selection chooses the information used by a model based on relevance, availability, stability and validation. A predictive association does not by itself show that a variable causes default or will remain useful after conditions change.');
 add('Data leakage','leakage|leaky','Data leakage occurs when model development uses information that would not have been available at the actual decision time or that improperly reveals the target. It can make reported performance look strong while producing an unusable model.');
 add('Training, validation and test samples','training|validation|test sample|out-of-time','Training data are used to fit a model, while validation and test data assess choices or performance outside that fitting process. An out-of-time sample helps test whether performance survives a change in observation period.');
 add('Logistic regression','logistic|log-odds','Logistic regression maps a linear combination of predictors into a probability through a logistic function. Its coefficients affect log-odds, so a coefficient is not directly a percentage-point change in PD.');
 add('Weight of evidence and information value','WoE|WOE|IV|information value','Weight of evidence compares the distribution of outcomes across variable groups under the stated convention. Information value summarises the resulting separation. Their use requires checks for sample size, leakage and stability rather than reliance on a universal cutoff.');
 add('Discrimination, ROC and AUC','discrimination|ROC|AUC|Gini','Discrimination measures how well a score orders risk between outcomes. The ROC curve summarises detection rates at different thresholds, and AUC measures the area under that curve. Good ranking does not establish that the probabilities are well calibrated.');
 add('Probability calibration and Brier score','Brier|calibration slope','Probability calibration compares predicted probabilities with observed frequencies under the evaluation design. A Brier score averages squared probability errors, combining aspects of accuracy that differ from rank discrimination alone.');
 add('Population stability index','PSI|stability','The population stability index compares the distribution of a variable or score across samples using defined bins. It is a diagnostic of distribution change, not a universal proof that model performance has deteriorated.');
 add('Multicollinearity','collinearity|correlated predictors','Multicollinearity occurs when predictors contain strongly overlapping information. It can make estimated coefficients unstable even if overall predictions appear adequate.');
 add('Overfitting and regularisation','overfitting|regularisation|regularization','Overfitting occurs when a model captures sample-specific noise that does not generalise. Regularisation constrains the fitting process, but it does not replace appropriate data separation and validation.');
 add('Provision matrix','provision matrix|loss rate','A provision matrix applies estimated lifetime loss rates to grouped receivables under the relevant simplified approach. The rates should reflect suitable segmentation and forward-looking information; they are not automatically annual PDs.');
 add('Modification and derecognition','modification|derecognition','A modification changes contractual terms. Derecognition removes an asset from the accounts when the applicable conditions are met; a modification does not automatically imply derecognition or a cure of credit deterioration.');
 add('Loss allowance and write-off','allowance|write-off|write-offs','A loss allowance records the relevant impairment estimate. A write-off reduces the carrying amount when the accounting criteria are met, which is different from deciding that collection or enforcement must always stop.');
 add('Overlay','overlays|post-model adjustment','An overlay is a documented adjustment used to address relevant risk or information not adequately reflected in a model output. It should not become an unexplained means of reaching a preferred allowance total.');
 add('RAROC and economic capital','RAROC|economic capital|hurdle','Risk-adjusted return on capital compares the specified risk-adjusted income with allocated capital. A hurdle is the required return used in the decision. Economic capital is an internal risk-based measure and need not equal regulatory capital.');
 add('Internal ratings-based approach','IRB','The internal ratings-based approach uses approved internal credit-risk inputs within a prescribed regulatory framework. Eligibility, floors and calculation conventions differ from those used to estimate accounting ECL.');
 add('SIMM and ISDA','SIMM|ISDA','The Standard Initial Margin Model is ISDA’s sensitivity-based model for initial margin on the relevant derivatives portfolios. ISDA is the International Swaps and Derivatives Association, which publishes the identified methodology and related standards.');
 add('SIMM product classes','RatesFX|product class','SIMM assigns trades to product classes and calculates their margin separately before adding the class totals. A product class can contain several risk classes; RatesFX is the combined rates and foreign-exchange product class.');
 add('SIMM concentration factor','CR|VCR','SIMM’s concentration factors increase the treatment of sufficiently large risk positions under the prescribed grouping and thresholds. CR refers to the relevant delta factor and VCR to the vega factor in the applets; their aggregation groups are not identical across risk classes.');
 add('SIMM bucket K and directional S','bucket K|capped S|K1|K2|S1|S2','In SIMM aggregation, K measures a bucket’s risk magnitude. S carries the signed sum into the next aggregation layer after applying the prescribed bounds. They have different roles and should not be substituted for one another.');
 add('Vega exposure, VRW and HVR','VR|VRW|HVR','SIMM transforms vega into the specified volatility-risk exposure before applying a vega risk weight and applicable concentration factor. VRW is the vega risk weight, while HVR is the historical volatility ratio used in the specified risk-class treatment.');
 add('SIMM theta and lambda','theta|lambda','In the SIMM curvature lesson, theta summarises the relevant signed curvature exposure and lambda is the resulting tail multiplier. These symbols have different meanings in other pricing or probability models, so their local formula definitions govern.');
 add('Base correlation and BC01','base correlation|BC01','Base correlation is a risk input associated with the credit-index tranche valuation framework described by the method. BC01 measures sensitivity to a one-percentage-point base-correlation change and is separate from the correlation used to aggregate ordinary credit-spread sensitivities.');
 add('CRIF','Common Risk Interchange Format','The Common Risk Interchange Format standardises exchanged risk records. Consistent formatting helps reconciliation, but it does not establish that trade populations, pricing, units or risk-factor mappings are correct.');
 add('Regridding','re-grid|regridding','Regridding expresses risk calculated on one set of tenors or factors on another required grid. Preserving a numerical sum is useful but does not alone prove that the transformed risk reproduces the intended valuation behaviour.');
 add('Incremental and standalone risk','incremental|standalone','Standalone risk measures a position by itself. Incremental risk is the change in portfolio risk when the position is added; it can be negative when the new position hedges an existing exposure.');
 add('Segregation','segregated|bankruptcy-remote','Segregation separates collateral or assets under specified legal arrangements. Bankruptcy-remoteness and permitted reuse depend on the actual structure, so received initial margin cannot automatically be assumed available to fund posted margin.');
 add('Remediation and add-ons','remediation|add-on|add-ons','Remediation addresses a model or control deficiency through documented actions. An add-on is an additional required amount under the relevant method or agreement; its basis and governance should remain separate from unexplained changes to raw sensitivities.');
 add('Model risk','model risk|model uncertainty','Model risk is the risk of adverse decisions caused by an inappropriate model, incorrect implementation, unreliable inputs or misuse of results. Validation should examine assumptions and limitations as well as numerical correctness.');
 add('Reconciliation','reconcile|reconciled','Reconciliation compares records or results and traces differences to their source. For risk calculations, this includes trade population, valuation time, units, currency, mapping, assumptions and model version.');
 add('Interest rate','interest rates','An interest rate expresses the cost of borrowing or the return on lending over a stated period. Its meaning depends on the currency, term, compounding convention and credit or collateral conditions.');
 add('Yield','yields|yield to maturity','A yield is a rate of return implied by a price and a specified cash-flow convention. Yield to maturity is the single discount rate that equates a bond’s promised payments to its price; realised returns can differ.');
 add('Duration','Macaulay duration|duration gap','Duration summarises the timing of cash flows or their sensitivity to rates, depending on the definition. Macaulay duration is a present-value-weighted time, while modified duration estimates proportional price sensitivity to yield.');
 add('Volatility smile and skew','smile|skew','A volatility smile or skew describes how quoted implied volatility varies across strikes for a given expiry. Using one constant volatility omits this market pattern and can miss risk when the pattern changes.');
 add('Bid–ask spread','bid/ask|bid-ask','The bid is the price at which a dealer offers to buy, and the ask is the price at which the dealer offers to sell. Their difference is a trading cost and can widen when markets become less liquid.');
 add('ColVA','collateral valuation adjustment','Collateral valuation adjustment captures the valuation effect of collateral remuneration or funding terms relative to the clean pricing benchmark in the chosen framework. Its treatment must be consistent with the other funding adjustments to avoid double counting.');
 add('Ridge penalty','ridge','A ridge penalty discourages large fitted coefficients by adding a squared-coefficient penalty to the fitting objective. It can improve stability, but the strength of the penalty must be selected and validated.');
 add('Imputation','imputed|missing values','Imputation supplies a value for a missing observation under a stated rule. The rule should be fitted using appropriate training data and checked for whether missingness itself contains risk information.');
 add('Standardisation','standardization|standardised predictor','Standardisation rescales a variable, often by subtracting a training-sample mean and dividing by its standard deviation. Applying the same fitted transformation to later observations avoids using future information.');
 add('Absorbing state','absorbing','An absorbing state is a model state that cannot be left once entered. Treating default as absorbing is a modelling choice that excludes subsequent cures from that transition model.');
 add('Markov assumption','Markov','The Markov assumption makes the next-state distribution depend on the current state rather than the complete past. A rating-transition model using this assumption can miss additional information in a borrower’s history.');
 add('Leverage','leveraged','Leverage increases exposure relative to the capital supporting it, often through borrowing or derivatives. It can magnify gains and losses and create funding pressure even when a position is expected to be profitable.');
 add('Wrong-way and right-way exposure','right-way','Right-way risk describes exposure that tends to fall as a counterparty becomes more likely to default. Wrong-way risk describes the opposite relationship, which can increase losses beyond an independence-based estimate.');
 add('Stationarity','stationary','Stationarity describes a model whose specified statistical properties remain stable over time. A stationary-curve assumption in an income example is narrower: it holds the chosen curve behaviour fixed over the projection convention.');
 add('Settlement','settlement lag','Settlement is the completion of a payment or delivery obligation. A settlement lag separates the trade date from completion and can create cash needs and exposure before the exchange is final.');
 add('Accrued interest','accrual|accrued','Accrued interest is interest earned or owed since the last payment date but not yet paid. Its calculation depends on the contract’s day-count and payment conventions.');
 add('Discount factor extrapolation','extrapolation','Extrapolation estimates a curve beyond its observed maturities. Unlike interpolation, it extends outside the available data and can make long-dated values particularly sensitive to the chosen assumptions.');
 add('SF in SIMM curvature','curvature scaling','In a SIMM curvature calculation, the scaling factor converts volatility exposure into the prescribed curvature exposure using the applicable maturity convention. It is distinct from the supervisory factor used in SA-CCR.');
})();
